using System;

namespace EfMigrationPack
{
    /// <summary>Marks a migration generated by ef-pack.</summary>
    [AttributeUsage(AttributeTargets.Class, Inherited = false)]
    public sealed class PackedMigrationAttribute : Attribute
    {
    }

    /// <summary>Records the original migration id of a step inside a packed migration.</summary>
    [AttributeUsage(AttributeTargets.Class, Inherited = false)]
    public sealed class PackedStepAttribute : Attribute
    {
        /// <summary>Creates the attribute.</summary>
        /// <param name="migrationId">The id the migration had before it was packed.</param>
        public PackedStepAttribute(string migrationId)
        {
            MigrationId = migrationId;
        }

        /// <summary>The id the migration had before it was packed.</summary>
        public string MigrationId { get; }
    }
}
